/** @typedef {import('../types.js').EmailFolder} EmailFolder */
/** @typedef {import('../types.js').EmailSummary} EmailSummary */
/** @type {Record<EmailFolder, string>} */
export const FOLDER_DIRS: Record<EmailFolder, string>;
export const DEFAULT_FOLDER: EmailFolder;
export const DEFAULT_LIMIT: 50;
export const MAX_LIMIT: 1000;
export function normalizeFolder(folder: unknown): EmailFolder;
export function normalizeLimit(limit: unknown): number;
export function folderRoot(folder: EmailFolder): string;
export function dayPath(folder: EmailFolder, day: string): string;
export function isUuidV7(id: unknown): id is string;
export function isDayName(name: string): boolean;
export function uuidV7Date(id: string): Date;
export function dayOf(date: Date): string;
export function candidateDays(id: string): string[];
export function decodeSubject(encoded: string): string;
export function parseEntryName(name: string): {
    id: string;
    subject: string;
} | null;
export function toSummary(entry: {
    name: string;
    path: string;
    uid: string;
    size?: number | null;
    is_dir?: boolean | number;
}, folder: EmailFolder): EmailSummary | null;
export function encodeCursor({ folder, day, fsCursor, daysCursor }: ListPosition): string;
export function decodeCursor(cursor: unknown, folder: EmailFolder): ListPosition | undefined;
export function isMissingDirectory(e: unknown): boolean;
export type EmailFolder = import("../types.js").EmailFolder;
export type EmailSummary = import("../types.js").EmailSummary;
/**
 * Where a listing resumes: the day folder being walked; while it still has
 * pages, the readdir cursor within it; and the readdir cursor of the page of
 * day folders that day was read from, so resuming does not re-list every day
 * newer than it. A cursor without that last part (issued before it existed)
 * walks the days from the top, which is only slower.
 */
export type ListPosition = {
    folder: EmailFolder;
    day: string;
    fsCursor?: string;
    daysCursor?: string;
};
